import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DxgWTcNC.js";const g=JSON.parse('{"title":"Strings, Cross-References, and Data Flow","description":"","frontmatter":{},"headers":[],"relativePath":"part2/11-strings-xrefs-data-flow.md","filePath":"part2/11-strings-xrefs-data-flow.md","lastUpdated":null}'),i={name:"part2/11-strings-xrefs-data-flow.md"};function o(p,e,r,d,l,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="strings-cross-references-and-data-flow" tabindex="-1">Strings, Cross-References, and Data Flow <a class="header-anchor" href="#strings-cross-references-and-data-flow" aria-label="Permalink to &quot;Strings, Cross-References, and Data Flow&quot;">​</a></h1><p>Strings are the cheapest, fastest source of insight in any binary. Cross-references turn the binary from a flat byte sequence into a graph you can walk. Following data flow turns &quot;this register holds a value&quot; into &quot;this register holds the second argument that was set 80 instructions ago by a configuration parser&quot;. This chapter covers the three together because they reinforce each other constantly: a useful string leads to its xrefs, which lead to a function, whose locals flow back to the original input.</p><h2 id="strings" tabindex="-1">Strings <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;Strings&quot;">​</a></h2><p>Three commands, three different scopes:</p><table tabindex="0"><thead><tr><th>Command</th><th>Scope</th></tr></thead><tbody><tr><td><code>iz</code></td><td>strings in data sections (<code>.rodata</code>, <code>.data</code>)</td></tr><tr><td><code>izz</code></td><td>strings <em>anywhere</em> in the file (slow on big binaries)</td></tr><tr><td><code>izzz</code></td><td>every string, including encodings beyond ASCII/UTF-8</td></tr></tbody></table><p>For embedded firmware, <strong>always use <code>izz</code></strong>. Section information is unreliable for raw blobs; strings live wherever the linker happened to put them.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08000000]&gt; izz | head -20</span></span>
<span class="line"><span>0x080001a0  &quot;ARM_MATH_CM4&quot;</span></span>
<span class="line"><span>0x080001ad  &quot;stm32f4xx_hal_gpio.c&quot;</span></span>
<span class="line"><span>0x080001c2  &quot;GPIOx is NULL&quot;</span></span>
<span class="line"><span>0x080001d0  &quot;Init-&gt;Pin invalid&quot;</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Each string entry shows the address, the string, and (in the full output) length and encoding. Filter:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; izz ~ \\.c            # source file names</span></span>
<span class="line"><span>[0x...]&gt; izz ~ ^http</span></span>
<span class="line"><span>[0x...]&gt; izz ~i password      # case-insensitive</span></span>
<span class="line"><span>[0x...]&gt; izz~ %d              # likely format strings</span></span></code></pre></div><p>The <code>~</code> operator is r2&#39;s grep (Chapter 3). For repeating patterns (MAC address-shaped strings, IPv4 literals, URL prefixes), use a shell pipe:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; izz | grep -E &#39;([0-9a-f]{2}:){5}[0-9a-f]{2}&#39;  # MACs</span></span>
<span class="line"><span>[0x...]&gt; izz | grep -E &#39;\\b[0-9]{1,3}(\\.[0-9]{1,3}){3}\\b&#39;  # IPs</span></span></code></pre></div><h2 id="strings-as-flags" tabindex="-1">Strings as flags <a class="header-anchor" href="#strings-as-flags" aria-label="Permalink to &quot;Strings as flags&quot;">​</a></h2><p>Each discovered string becomes a flag in the <code>strings</code> flag space:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; fs strings</span></span>
<span class="line"><span>[0x...]&gt; f</span></span>
<span class="line"><span>0x080001a0  12  str.ARM_MATH_CM4</span></span>
<span class="line"><span>0x080001ad  20  str.stm32f4xx_hal_gpio_c</span></span>
<span class="line"><span>0x080001c2  13  str.GPIOx_is_NULL</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Now you can reference the string by name everywhere:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; axt @ str.GPIOx_is_NULL    # who references this error message?</span></span>
<span class="line"><span>[0x...]&gt; pdf @ \`axt @ str.GPIOx_is_NULL ~[1]\`   # decompile the caller</span></span></code></pre></div><p>This is the single most useful debugging trick in r2: an error string points back to the function that emitted it, which gives you the function&#39;s purpose for free.</p><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><p><code>ax*</code> is the cross-reference subsystem.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>ax</code></td><td>list all xrefs</td></tr><tr><td><code>axt @ addr</code></td><td>xrefs <strong>to</strong> <code>addr</code> (who points here?)</td></tr><tr><td><code>axf @ addr</code></td><td>xrefs <strong>from</strong> <code>addr</code> (who/what does <code>addr</code> point to?)</td></tr><tr><td><code>axg @ addr</code></td><td>xref graph at <code>addr</code></td></tr><tr><td><code>ax addr1 addr2</code></td><td>manually create xref from <code>addr1</code> to <code>addr2</code></td></tr><tr><td><code>ax-</code></td><td>delete xref</td></tr><tr><td><code>aex addr</code></td><td>track xrefs by ESIL emulation</td></tr><tr><td><code>aax</code></td><td>analyse all xrefs</td></tr><tr><td><code>aar</code></td><td>analyse references in data</td></tr></tbody></table><p><code>axt</code> and <code>axf</code> are the workhorses. The mnemonic that helps remember which is which: <strong>t</strong> is <strong>t</strong>oward (xrefs that come toward this address); <strong>f</strong> is <strong>f</strong>rom (xrefs that go from this address). Most of the time you want <code>axt</code> — &quot;who calls this function?&quot;</p><p>Iteration patterns:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; pd 1 @@= \`axt @ sym.imp.malloc ~[1]\`   # disasm of every malloc caller</span></span>
<span class="line"><span>[0x...]&gt; pdf @@= \`axt @ str.password ~[1]\`      # decompile every caller of pwd code</span></span>
<span class="line"><span>[0x...]&gt; CC &quot;calls printf&quot; @@= \`axt @ sym.printf ~[1]\`  # comment every caller</span></span></code></pre></div><p>For a function-level view, <code>axg</code> produces a graph in dot/mermaid format you can render:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; axg @ sym.handle_packet &gt; /tmp/g.dot</span></span>
<span class="line"><span>$ dot -Tpng /tmp/g.dot &gt; g.png</span></span></code></pre></div><h2 id="data-references" tabindex="-1">Data references <a class="header-anchor" href="#data-references" aria-label="Permalink to &quot;Data references&quot;">​</a></h2><p>R2 distinguishes three kinds of cross-references:</p><ul><li><strong>CALL</strong> — a function call (BL on ARM, JAL on RISC-V, …).</li><li><strong>JMP</strong> — a branch within or to another function.</li><li><strong>DATA</strong> — a load/store that addresses some location.</li></ul><p>The third is the one that catches strings, MMIO accesses, and lookup tables. You can filter by type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; axt @ 0x40021018         # all xrefs (probably DATA from MMIO accesses)</span></span>
<span class="line"><span>[0x...]&gt; ax | grep DATA           # all DATA xrefs in the binary</span></span></code></pre></div><p>For a peripheral register, the DATA xrefs tell you every place in the firmware that touches that register — invaluable for understanding peripheral usage. Combine with type linking (Chapter 8) and you can trace every write to <code>USART1-&gt;CR1</code> and figure out the UART configuration sequence.</p><h2 id="manual-xrefs" tabindex="-1">Manual xrefs <a class="header-anchor" href="#manual-xrefs" aria-label="Permalink to &quot;Manual xrefs&quot;">​</a></h2><p>Sometimes r2 misses a reference. The most common case is a computed function pointer call:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; pd 5 @ 0x08001234</span></span>
<span class="line"><span>ldr r3, =fn_table</span></span>
<span class="line"><span>ldr r4, [r3, r0, lsl 2]   ; r0 is the index</span></span>
<span class="line"><span>blx r4                    ; r2 has no idea where this goes</span></span></code></pre></div><p>If you can statically resolve the table and the index, add the xrefs manually:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ax 0x08001234 0x08010000   # call from caller to table[0]</span></span>
<span class="line"><span>[0x...]&gt; ax 0x08001234 0x08010100   # call from caller to table[1]</span></span>
<span class="line"><span>[0x...]&gt; ax 0x08001234 0x08010200   # call from caller to table[2]</span></span></code></pre></div><p>Now <code>axt @ 0x08010000</code> reports the call site. The decompiler also picks up the resolution and renders meaningful names (if you set them).</p><p>For very large dispatch tables, write an r2pipe script (Chapter 25) that walks the table and emits <code>ax</code> commands.</p><h2 id="following-data-flow" tabindex="-1">Following data flow <a class="header-anchor" href="#following-data-flow" aria-label="Permalink to &quot;Following data flow&quot;">​</a></h2><p>For non-trivial flow analysis, r2 has two approaches: <strong>ESIL emulation</strong> and <strong>type propagation</strong>.</p><p>ESIL emulation runs a function symbolically:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; aei                       # initialise ESIL VM</span></span>
<span class="line"><span>[0x...]&gt; aeim                      # initialise memory</span></span>
<span class="line"><span>[0x...]&gt; aeip                      # set ESIL pc to current</span></span>
<span class="line"><span>[0x...]&gt; aes                       # step</span></span>
<span class="line"><span>[0x...]&gt; aer                       # ESIL register state</span></span>
<span class="line"><span>[0x...]&gt; aer r0                    # value of r0</span></span></code></pre></div><p>Step through a function until you reach the line whose data flow you want to inspect, then read registers. For a constant-folding question (&quot;what value reaches this comparison?&quot;), this is faster than reading the disassembly cold. Chapter 21 covers ESIL in depth.</p><p>Type propagation (<code>aft</code>) follows variables through a function based on the types you set:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; afs int handle_packet(uint8_t *buf, size_t len) @ sym.handle_packet</span></span>
<span class="line"><span>[0x...]&gt; aft @ sym.handle_packet</span></span></code></pre></div><p>After <code>aft</code>, every load through <code>buf</code> is typed <code>uint8_t</code>, every arithmetic on <code>len</code> is typed <code>size_t</code>. The decompiler renders the function with those types intact.</p><h2 id="a-worked-example" tabindex="-1">A worked example <a class="header-anchor" href="#a-worked-example" aria-label="Permalink to &quot;A worked example&quot;">​</a></h2><p>Suppose you find an interesting string:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; izz ~ &quot;fan speed&quot;</span></span>
<span class="line"><span>0x080012a8  &quot;fan speed: %d RPM&quot;</span></span></code></pre></div><p>Find who references it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; axt @ str.fan_speed_d_RPM</span></span>
<span class="line"><span>0x08001234  -&gt; str.fan_speed_d_RPM   (DATA in fcn.print_status)</span></span></code></pre></div><p>Open the function:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; pdf @ fcn.print_status</span></span></code></pre></div><p>You see it loads the address of the string, calls <code>printf</code> with it, and the second argument comes from a pointer parameter dereferenced at offset <code>+0x4</code>. The function reads:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#DCBDFB;"> print_status</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> sensor_state </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">*</span><span style="--shiki-light:#E36209;--shiki-dark:#F69D50;">st</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#DCBDFB;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;fan speed: </span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;">%d</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> RPM&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, st-&gt;fan_rpm);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">}</span></span></code></pre></div><p>Now find who calls <code>print_status</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; axt @ fcn.print_status</span></span>
<span class="line"><span>0x08001500  -&gt; fcn.print_status   (CALL in fcn.main_loop)</span></span></code></pre></div><p>Walk up: who calls <code>main_loop</code>? Eventually you reach the entry function. Now you have a top-down map of the firmware&#39;s reporting path, all from one string.</p><h2 id="stable-workflow-patterns" tabindex="-1">Stable workflow patterns <a class="header-anchor" href="#stable-workflow-patterns" aria-label="Permalink to &quot;Stable workflow patterns&quot;">​</a></h2><p>Three patterns that come up daily:</p><p><strong>String -&gt; function -&gt; caller</strong>: find an error string, trace its references back to find the function emitting it, then find the function&#39;s callers. Typically gets you from &quot;what does this firmware do?&quot; to &quot;here&#39;s the part that handles X&quot; in five minutes.</p><p><strong>Constant -&gt; users</strong>: find a magic constant (a vendor product ID, a protocol opcode, a CRC polynomial) and trace its references to find every place that touches that protocol/feature.</p><p><strong>Peripheral -&gt; users</strong>: find a peripheral base address (<code>0x40021000</code> for STM32 RCC), trace DATA xrefs to find every clock manipulation in the firmware. Combine with HAL signatures and you have a clock configuration map.</p><p>Get good at these three patterns and you will understand new firmware faster than people who try to read it linearly.</p>`,64)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
